"use client";
import React, { useState } from 'react';
import { mockDb } from '@/lib/store/mockDb';
import { EvolutionNote } from '@/types';
import { Save, History, User as UserIcon, Pill } from 'lucide-react';

export default function PatientFile({ params }: { params: { id: string } }) {
  const patient = mockDb.getPatientById(params.id);
  const [evolutions, setEvolutions] = useState(mockDb.getEvolutionsByPatient(params.id));
  const [newNote, setNewNote] = useState({ symptoms: '', diagnosis: '', treatment: '' });

  const handleSaveEvolution = () => {
    const saved = mockDb.addEvolution({
      patientId: params.id,
      doctorId: 'd1', // Simulado
      ...newNote
    });
    setEvolutions([saved, ...evolutions]);
    setNewNote({ symptoms: '', diagnosis: '', treatment: '' });
  };

  return (
    <div className="p-6 max-w-6xl mx-auto bg-gray-50 min-h-screen font-sans">
      <div className="flex items-center justify-between mb-8">
        <h1 className="text-3xl font-bold text-blue-900">Ficha Médica de Paciente</h1>
        <div className="flex gap-2">
          <span className={`px-3 py-1 rounded-full text-xs font-bold ${patient.profileStatus === 'verified' ? 'bg-green-100 text-green-700' : 'bg-yellow-100 text-yellow-700'}`}>
            {patient.profileStatus.replace('_', ' ').toUpperCase()}
          </span>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {/* Info Personal */}
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
          <div className="flex items-center gap-3 mb-4 text-blue-600">
            <UserIcon size={20} />
            <h2 className="font-semibold">Datos Personales</h2>
          </div>
          <div className="space-y-3 text-sm text-gray-600">
            <p><strong>Nombre:</strong> {patient.name}</p>
            <p><strong>Email:</strong> {patient.email}</p>
            <p><strong>Tlf:</strong> {patient.phoneNumber}</p>
            <div className="pt-4 border-t">
              <p><strong>Sangre:</strong> {patient.personalData?.bloodType || 'No reg.'}</p>
              <p><strong>Cédula:</strong> {patient.personalData?.idCardNumber || 'No reg.'}</p>
              <p><strong>Alergias:</strong> {patient.personalData?.allergies.join(', ') || 'Ninguna'}</p>
            </div>
          </div>
        </div>

        {/* Editor de Evolución */}
        <div className="md:col-span-2 bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
          <div className="flex items-center gap-3 mb-4 text-blue-600">
            <Save size={20} />
            <h2 className="font-semibold">Nueva Nota de Evolución</h2>
          </div>
          <div className="grid gap-4">
            <textarea 
              placeholder="Síntomas y motivo de consulta..." 
              className="w-full p-3 border rounded-xl text-sm focus:ring-2 ring-blue-200 outline-none" 
              rows={3}
              value={newNote.symptoms}
              onChange={e => setNewNote({...newNote, symptoms: e.target.value})}
            />
            <textarea 
              placeholder="Diagnóstico médico..." 
              className="w-full p-3 border rounded-xl text-sm focus:ring-2 ring-blue-200 outline-none" 
              rows={2}
              value={newNote.diagnosis}
              onChange={e => setNewNote({...newNote, diagnosis: e.target.value})}
            />
            <textarea 
              placeholder="Tratamiento y recomendaciones..." 
              className="w-full p-3 border rounded-xl text-sm focus:ring-2 ring-blue-200 outline-none" 
              rows={2}
              value={newNote.treatment}
              onChange={e => setNewNote({...newNote, treatment: e.target.value})}
            />
            <button 
              onClick={handleSaveEvolution}
              className="bg-blue-600 text-white px-6 py-2 rounded-xl font-medium hover:bg-blue-700 transition-colors"
            >
              Guardar Evolución
            </button>
          </div>
        </div>
      </div>

      {/* Historial de Evoluciones */}
      <div className="mt-8 bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
        <div className="flex items-center gap-3 mb-6 text-blue-600">
          <History size={20} />
          <h2 className="font-semibold">Línea de Tiempo de Evolución</h2>
        </div>
        <div className="space-y-6">
          {evolutions.map((evo) => (
            <div key={evo.id} className="flex gap-4 p-4 bg-blue-50 rounded-xl border-l-4 border-blue-500">
              <div className="text-xs text-gray-500 min-w-[100px]">
                {new Date(evo.date).toLocaleDateString()} <br/>
                {new Date(evo.date).toLocaleTimeString()}
              </div>
              <div className="flex-1">
                <p className="text-sm font-bold text-gray-800">Síntomas: {evo.symptoms}</p>
                <p className="text-sm text-gray-700 mt-1"><strong>Diagnóstico:</strong> {evo.diagnosis}</p>
                <p className="text-sm text-gray-600 mt-1 italic"><strong>Tratamiento:</strong> {evo.treatment}</p>
              </div>
            </div>
          ))}
          {evolutions.length === 0 && <p className="text-gray-400 text-center py-4">No hay evoluciones registradas.</p>}
        </div>
      </div>
    </div>
  );
}

