              <label className="text-xs font-bold text-gray-400 uppercase">Fecha de Nacimiento</label>
              <input 
                type="date"
                name="birthDate"
                value={formData.birthDate}
                onChange={handleInputChange}
                className="w-full p-3 border rounded-xl text-sm focus:ring-2 ring-blue-200 outline-none" 
              />
            </div>

            <div className="space-y-2">
              <label className="text-xs font-bold text-gray-400 uppercase">Género</label>
              <select 
                name="gender"
                value={formData.gender}
                onChange={handleInputChange}
                className="w-full p-3 border rounded-xl text-sm focus:ring-2 ring-blue-200 outline-none"
              >
                <option value="">Seleccione...</option>
                <option value="Masculino">Masculino</option>
                <option value="Femenino">Femenino</option>
                <option value="Otro">Otro</option>
              </select>
            </div>

            <div className="md:col-span-2 space-y-2">
              <label className="text-xs font-bold text-gray-400 uppercase">Alergias / Enfermedades Crónicas</label>
              <textarea 
                placeholder="Ej: Alérgico a la Penicilina, Diabetes Tipo 2..." 
                className="w-full p-3 border rounded-xl text-sm focus:ring-2 ring-blue-200 outline-none" 
                rows={3}
                value={formData.allergies.join(', ')}
                onChange={(e) => setFormData({...formData, allergies: e.target.value.split(',')})}
              />
            </div>
          </div>

          <button 
            className="mt-8 w-full bg-blue-600 text-white py-4 rounded-2xl font-bold hover:bg-blue-700 transition-all shadow-lg shadow-blue-200"
            onClick={() => alert('Datos guardados. Esperando validación física en recepción.')}
          >
            Guardar y Enviar Ficha
          </button>
        </div>
      </div>
    </div>
  );
}

